/* --- husos horarios / hora local -> UT --- */
function zoneOffsetMin(instantMs,tz){
  try{
    var dtf=new Intl.DateTimeFormat('en-US',{timeZone:tz,hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});
    var p={},parts=dtf.formatToParts(new Date(instantMs)),i;
    for(i=0;i<parts.length;i++)p[parts[i].type]=parts[i].value;
    var h=p.hour==='24'?0:+p.hour;
    var asUTC=Date.UTC(+p.year,+p.month-1,+p.day,h,+p.minute,+p.second);
    return Math.round((asUTC-instantMs)/60000);
  }catch(e){return null;}
}
/* devuelve {jd, offMin} para fecha/hora local en tz (o con offset manual en horas) */
function localToJD(Y,M,D,hh,mm,tz,manualOffH){
  var offMin;
  if(tz){
    var guess=Date.UTC(Y,M-1,D,hh,mm,0);
    offMin=zoneOffsetMin(guess,tz);
    if(offMin===null)offMin=(manualOffH||0)*60;
    else{var inst=guess-offMin*60000;offMin=zoneOffsetMin(inst,tz);}
  } else { offMin=(manualOffH||0)*60; }
  var utMs=Date.UTC(Y,M-1,D,hh,mm,0)-offMin*60000;
  var u=new Date(utMs);
  var jd=A.julianDay(u.getUTCFullYear(),u.getUTCMonth()+1,u.getUTCDate(),u.getUTCHours()+u.getUTCMinutes()/60+u.getUTCSeconds()/3600);
  return {jd:jd,offMin:offMin};
}
function jdNoonUT(Y,M,D){return A.julianDay(Y,M,D,12);}

/* --- posiciones natales --- */
var PNAMES=['Sun','Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto'];
function natalPositions(jd){
  var o={},i;
  for(i=0;i<PNAMES.length;i++)o[PNAMES[i]]=A.planetLon(PNAMES[i],jd);
  o.Moon=A.moonLon(jd);
  o.Node=A.meanNode(jd);
  return o;
}

/* --- año decimal -> jd --- */
function yearToJD(y){return 2451545.0+(y-2000.0)*365.25;}
/* --- longitud del tránsito según el cuerpo --- */
function transitLon(body,jd){
  if(body==='Pluto')return A.planetLon('Pluto',jd);
  if(body==='Uranus')return A.planetLon('Uranus',jd);
  if(body==='SatNep'){var s=A.planetLon('Saturn',jd),n=A.planetLon('Neptune',jd);
    return norm360(s+normpm(n-s)/2);}
  return 0;
}
/* separación mínima a un ángulo de aspecto */
function aspDist(a,b,ang){var diff=Math.abs(normpm(a-b));return Math.abs(diff-ang);}

var ASPECTS=[{n:'Conjunción',a:0},{n:'Sextil',a:60},{n:'Cuadratura',a:90},{n:'Trígono',a:120},{n:'Oposición',a:180}];
var MESES=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
function decYearToLabel(y){var yr=Math.floor(y);var mo=Math.floor((y-yr)*12);if(mo<0)mo=0;if(mo>11)mo=11;return MESES[mo]+' '+yr;}

/* escaneo de aspectos del tránsito a los puntos natales */
function scanAspects(body,y0,y1,targets,orb,moonRange){
  var out=[],t,asp;
  for(t=0;t<targets.length;t++){
    var tgt=targets[t];
    for(asp=0;asp<ASPECTS.length;asp++){
      var A1=ASPECTS[asp], inWin=false, winS=0, best=0, bestd=99;
      var step=1/12, y;
      for(y=y0;y<=y1+1e-9;y+=step){
        var jd=yearToJD(y);
        var d=aspDist(transitLon(body,jd),tgt.lon,A1.a);
        var eff=(tgt.key==='Moon')?Math.max(0,d-moonRange):d;
        if(eff<=orb){ if(!inWin){inWin=true;winS=y;best=y;bestd=d;} if(d<bestd){bestd=d;best=y;} }
        else if(inWin){ out.push({tgt:tgt,asp:A1,winS:winS,winE:y-step,exact:best,approx:(tgt.key==='Moon'&&moonRange>0)}); inWin=false; }
      }
      if(inWin)out.push({tgt:tgt,asp:A1,winS:winS,winE:y1,exact:best,approx:(tgt.key==='Moon'&&moonRange>0)});
    }
  }
  out.sort(function(p,q){return p.exact-q.exact;});
  return out;
}

/* casa(s) que atraviesa un tramo de grados según cúspides */
function housesForRange(d0,d1,cusps){
  var set={},pts=[d0,(d0+d1)/2,d1],i;
  for(i=0;i<pts.length;i++)set[A.houseOf(pts[i],cusps)]=1;
  var arr=Object.keys(set).map(Number).sort(function(a,b){return a-b;});
  return arr;
}
/* casa whole-sign desde ascendente declarado */
function wholeSignHouse(signIdx,ascSignIdx){var h=signIdx-ascSignIdx+1;if(h<=0)h+=12;return h;}

